import fs from 'node:fs';import assert from 'node:assert/strict';import {hash,json} from './bounded-source-hash-20261026.mjs';
const stage='F:/VisibleMedicine/staging/20261027-coccygeus-website',baseFile=stage+'/SOURCE_BEFORE_ROLE.json',base=json(baseFile),site=base.website,parent=json(base.parent),role='tests/head-feature-source-roles.mjs',test='tests/head-native-history-current-transition.test.mjs';
assert(base.sourceSealPrecedesWebsiteVerification);for(const r of base.sourceRows)assert.equal(hash(site+'/'+r.path),r.sha256,r.path);
const inputs=json(site+'/atlas-review/integration-inputs.json');assert(!inputs.inputs.some(r=>[role,test].includes(r.path)),'Test-only seams must not alter Review binding');
const save=(p,v)=>fs.writeFileSync(p,JSON.stringify(v,null,2)+'\n',{flag:'wx'}),pin=p=>({path:p,sha256:hash(p)}),admission=stage+'/HEAD_DELIVERY_ADMISSION.json';
save(admission,{schema:'vm-head-delivery-admission/1',at:new Date().toISOString(),website:site,sourceBeforeRole:pin(baseFile),atlasHead:base.atlasHead,atlasTree:base.atlasTree,reviewBindingSha256:base.reviewBindingSha256,reviewSourceFiles:base.reviewSourceFiles,reviewInputs:base.protectedReviewInputs,viewerFiles:base.viewerFiles,viewerPackages:base.viewerPackages,sourceRows:base.sourceRows.filter(r=>![role,test].includes(r.path)),excludedSelfWitnesses:[role,test],clinicalApproval:false});
const edits=[];
function replaceExact(p,pairs){const original=fs.readFileSync(site+'/'+p,'utf8');assert.equal(hash(site+'/'+p),hash(parent.website+'/'+p));let result=original;for(const[from,to]of pairs){assert.equal(result.split(from).length,2,from);result=result.replace(from,to);}let inverse=result;for(const[from,to]of [...pairs].reverse())inverse=inverse.replace(to,from);assert.equal(inverse,original);fs.writeFileSync(site+'/'+p,result);edits.push({path:p,beforeSha256:hash(parent.website+'/'+p),afterSha256:hash(site+'/'+p),pairs,exactInverse:true});}
replaceExact(role,[["const admitted=sourceRole('F:/VisibleMedicine/staging/20261027-guided-focus-website/HEAD_DELIVERY_ADMISSION.json',\n 'd67c610c58e46ecf1e1a7802be46265c043f2ef5407c9af54dd88b80d7b873c3');",`const admitted=sourceRole('${admission}',\n '${hash(admission)}');`],["assert.equal(pin.source,'"+parent.atlasHead+"');","assert.equal(pin.source,'"+base.atlasHead+"');"],['actual current source matches independent guided-focus admission','actual current source matches independent coccygeus import admission']]);
replaceExact(test,[["const current=assertSealedCurrentHeadFeatureDelivery();assert.equal(current.source,'"+parent.atlasHead+"');","const current=assertSealedCurrentHeadFeatureDelivery();assert.equal(current.source,'"+base.atlasHead+"');"]]);
save(stage+'/ROLE_ADMISSION_TRANSITION.json',{at:new Date().toISOString(),edits,admission:pin(admission),allHistoricalAssertionsAndTamperedActualReadRefusalsPreserved:true,onlyCurrentDeliveryWitnessAndRevisionAdvanced:true});
const rows=base.sourceRows.map(r=>[role,test].includes(r.path)?{...r,bytes:fs.statSync(site+'/'+r.path).size,sha256:hash(site+'/'+r.path)}:r);
save(stage+'/SOURCE_CANDIDATE.json',{...base,at:new Date().toISOString(),sourceRows:rows,changedPaths:[...base.changedPaths,role,test],roleAdmission:pin(stage+'/ROLE_ADMISSION_TRANSITION.json'),allOriginalTestRootsAndHistoricalFixturesUnchanged:false,allHistoricalFixturesAndBehaviorAssertionsPreserved:true,onlyCurrentDeliveryWitnessesAdapted:true});
console.log(JSON.stringify({source:pin(stage+'/SOURCE_CANDIDATE.json'),paths:rows.length,reviewInputs:inputs.inputs.length,currentRoleAdaptedWithoutBehaviorChanges:true}));
